<h2>Calculate packaging box volume</h2><p class="lead">Calculate rectangular box volume, capacity and optional material-volume difference between outside and inside dimensions.</p><div class="notice">Use actual internal dimensions when capacity must be precise. Outside dimensions are often the relevant dimensions for storage and freight planning.</div><div class="form-grid"><div class="field"><label for="l">Length (cm)</label><input id="l" type="number" value="40" min="0.001" step="any"></div><div class="field"><label for="w">Width (cm)</label><input id="w" type="number" value="30" min="0.001" step="any"></div><div class="field"><label for="h">Height (cm)</label><input id="h" type="number" value="20" min="0.001" step="any"></div><div class="field"><label for="th">Wall thickness per side (mm, optional)</label><input id="th" type="number" value="3" min="0" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Outer volume</span><strong id="outer">—</strong></div><div class="metric"><span>Outer capacity</span><strong id="litres">—</strong></div><div class="metric"><span>Approx. inner volume</span><strong id="inner">—</strong></div><div class="metric"><span>Volume difference</span><strong id="material">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('outer').textContent='—';$('litres').textContent='—';$('inner').textContent='—';$('material').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const l=num('l'),w=num('w'),h=num('h'),t=num('th')/10;if(!(l>0&&w>0&&h>0&&t>=0&&2*t<Math.min(l,w,h)))throw 0;const ov=l*w*h,il=l-2*t,iw=w-2*t,ih=h-2*t,iv=il*iw*ih;$('outer').textContent=fmt(ov,0)+' cm³';$('litres').textContent=fmt(ov/1000,3)+' L';$('inner').textContent=fmt(iv/1000,3)+' L';$('material').textContent=fmt((ov-iv)/1000,3)+' L';$('note').textContent='Wall-thickness subtraction is a simple rectangular approximation. Corrugated board folds, flaps, compression and internal fittings change usable volume.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
